import { test } from 'node:test';
import assert from 'node:assert/strict';
import { businessDaysBetween } from '../src/business.js';

test('oculto: fins de semana', () => {
  assert.equal(businessDaysBetween('2026-10-02', '2026-10-05'), 1);
  assert.equal(businessDaysBetween('2026-10-05', '2026-10-05'), 0);
  assert.equal(businessDaysBetween('2026-10-05', '2026-10-16'), 9);
});
